using UnityEngine;

public class PlayerController : MonoBehaviour
{
    // Cachear en Awake, no buscar cada frame
    private Rigidbody rb;
    private Animator animator;

    void Awake()
    {
        // Auto-inicialización: cachear componentes propios
        rb = GetComponent<Rigidbody>();
        animator = GetComponent<Animator>();
    }

    void Start()
    {
        // Referencias cruzadas: otros objetos ya hicieron Awake
        // Ej: buscar al GameManager que ya se inicializó
    }

    void Update()
    {
        // Input cada frame
        float h = Input.GetAxis("Horizontal");
        animator.SetFloat("Speed", Mathf.Abs(h));
    }

    void FixedUpdate()
    {
        // Física en FixedUpdate, no en Update
        float h = Input.GetAxis("Horizontal");
        rb.AddForce(Vector3.right * h * 10f);
    }

    void LateUpdate()
    {
        // Cámara o lógica que depende de posiciones ya actualizadas
    }

    void OnDestroy()
    {
        // Limpiar suscripciones a eventos, liberar recursos
    }
}

